namespace ToneCustoms.ShellStudio.Export;
public sealed class GtaOutputVerifier { static readonly string[] ModelExt={".ydr",".ydd",".ymap"};public IReadOnlyList<string> Verify(string stream){var r=new List<string>();if(!Directory.Exists(stream)){r.Add("GTA stream output folder is missing");return r;}var files=Directory.GetFiles(stream);if(!files.Any(f=>ModelExt.Contains(Path.GetExtension(f),StringComparer.OrdinalIgnoreCase)))r.Add("No GTA drawable/map output detected");if(!files.Any(f=>Path.GetExtension(f).Equals(".ybn",StringComparison.OrdinalIgnoreCase)))r.Add("No GTA collision (.ybn) output detected");return r;} }
